40	 * Strip empty markdown links `[text]()` → `text`. Some MCP tools (notably
41	 * deepwiki) emit citation footnotes with no URL; rendering them as links
42	 * leaves visible empty parens in Slack/Telegram.
43	 */
44	function stripEmptyLinks(input: string): string {
45	  return input.replace(/\[([^\]]+)\]\(\s*\)/g, "$1");
46	}
47	
48	/**
49	 * Slack accepts up to 12,000 chars per `markdown_text` post. Keep a margin so
50	 * downstream emoji/mention expansion does not push us over the limit.
51	 */
52	const SLACK_MARKDOWN_CHUNK_SIZE = 11_000;
53	
54	/**
55	 * Split text on paragraph boundaries (`\n\n`) so we never break mid-sentence,
56	 * mid-list, or mid-code-fence when posting multiple chunks. Long paragraphs
57	 * that exceed the limit on their own fall back to line boundaries, then to
58	 * a hard slice as last resort.
59	 */
60	function chunkOnParagraphBoundaries(
61	  text: string,
62	  maxChunkSize: number
63	): string[] {
64	  if (text.length <= maxChunkSize) return [text];
65	
66	  const chunks: string[] = [];
67	  const paragraphs = text.split(/\n\n+/);
68	  let current = "";
69	
70	  const flush = () => {
71	    if (current.length > 0) {
72	      chunks.push(current);
73	      current = "";
74	    }
75	  };
76	
77	  const pushOversized = (chunk: string) => {
78	    // Try line boundaries first, then hard slice as a last resort.
79	    const lines = chunk.split("\n");
80	    let buf = "";
81	    for (const line of lines) {
82	      if (buf.length + line.length + 1 > maxChunkSize) {
83	        if (buf) chunks.push(buf);
84	        buf = "";
85	        if (line.length > maxChunkSize) {
86	          for (let i = 0; i < line.length; i += maxChunkSize) {
87	            const slice = line.slice(i, i + maxChunkSize);
88	            if (i + maxChunkSize >= line.length) {
89	              buf = slice;
90	            } else {
91	              chunks.push(slice);
92	            }
93	          }
94	        } else {
95	          buf = line;
96	        }
97	      } else {
98	        buf = buf ? `${buf}\n${line}` : line;
99	      }
100	    }
101	    if (buf) chunks.push(buf);
102	  };
103	
104	  for (const para of paragraphs) {
105	    if (para.length > maxChunkSize) {
106	      flush();
107	      pushOversized(para);
108	      continue;
109	    }
110	    const candidate = current ? `${current}\n\n${para}` : para;
111	    if (candidate.length > maxChunkSize) {
112	      flush();
113	      current = para;
114	    } else {
115	      current = candidate;
116	    }
117	  }
118	  flush();
119	  return chunks;
120	}
121	
122	/**
123	 * Post a text body to a Slack channel/thread using `chat.postMessage` with
124	 * `markdown_text`, so Slack renders markdown directly and does not HTML-escape
125	 * `<`, `>`, `&`. Splits long bodies on paragraph boundaries to avoid hitting
126	 * Slack's 12,000-char per-post limit.
127	 *
128	 * Returns true if the post was handled here, false if the caller should fall
129	 * back to the SDK's generic `target.post()` path.
130	 */
131	async function postSlackMarkdown(
132	  instance: any,
133	  channelId: string,
134	  conversationId: string | undefined,
135	  body: string
136	): Promise<boolean> {
137	  const adapter = instance.chat?.getAdapter?.("slack");
138	  const slackClient = adapter?.client;
139	  if (!slackClient?.chat?.postMessage) return false;
140	
141	  // channelId looks like "slack:C0123ABCD"; conversationId either equals it
142	  // (DM/channel-level) or is "slack:C0123ABCD:1700000000.123456" for a thread.
143	  const channel = channelId.startsWith("slack:")
