/**
 * Ambient-silence spike — which per-turn "say nothing" mechanism is most reliable?
 *
 * Three candidate designs for letting a `reply_to_source` agent decline to
 * speak on a given turn. All three run the REAL production model with the SAME
 * scenarios; the only difference is the mechanism offered and how "delivered"
 * is computed.
 *
 *   S (sentinel)  — prompt: "reply with exactly NO_REPLY if nothing to add".
 *                   Delivered = terminal text, unless it normalizes to NO_REPLY.
 *   T (tool)      — a `skip_reply` tool. Delivered = terminal text, unless the
 *                   model called skip_reply.
 *   I (inverted)  — terminal text is NEVER delivered; `send_message` is the only
 *                   channel. Delivered = whatever it sent.
 *
 * `send_message` exists in ALL arms (production agents have the conversation
 * plugin), so this also measures how often S/T double-post — the bug PR #2403
 * just fixed — as a side effect.
 *
 * Failure directions are asymmetric, which is the whole point of measuring:
 *   S and T fail toward NOISE   (model forgets the mechanism -> posts anyway)
 *   I      fails toward SILENCE (model forgets to send      -> user gets nothing)
 *
 * Usage: Z_AI_API_KEY=... bun silence-spike.ts [--trials N] [--model glm-5.2]
 */

import { getModel } from "@mariozechner/pi-ai";
import {
  AuthStorage,
  ModelRegistry,
  createAgentSession,
} from "@mariozechner/pi-coding-agent";
import { Type } from "@sinclair/typebox";

const Z_AI_BASE_URL =
  process.env.Z_AI_API_BASE_URL || "https://api.z.ai/api/coding/paas/v4";

const args = process.argv.slice(2);
const getArg = (flag: string, def: string) => {
  const i = args.indexOf(flag);
  return i >= 0 && args[i + 1] ? args[i + 1]! : def;
};
const TRIALS = Number(getArg("--trials", "3"));
const MODEL_ID = getArg("--model", "glm-5.2");

function buildModel() {
  const key = process.env.Z_AI_API_KEY;
  if (!key) throw new Error("Z_AI_API_KEY is required.");
  let base = getModel("zai" as never, MODEL_ID as never) as never as
    | Record<string, unknown>
    | undefined;
  if (!base) {
    base = {
      id: MODEL_ID,
      name: MODEL_ID,
      api: "openai-completions",
      provider: "zai",
      baseUrl: Z_AI_BASE_URL,
      reasoning: false,
      input: ["text"],
      cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
      contextWindow: 128000,
      maxTokens: 8192,
    };
  }
  const model = {
    ...base,
    baseUrl: Z_AI_BASE_URL,
    compat: {
      ...((base as { compat?: object }).compat ?? {}),
      supportsStore: false,
    },
  };
  const authStorage = new AuthStorage();
  authStorage.setRuntimeApiKey("zai", key);
  return { model, authStorage, modelRegistry: new ModelRegistry(authStorage) };
}

// --- scenarios -------------------------------------------------------------
// A CRM agent sitting in a busy #sales channel. `expect: "silent"` messages are
// ordinary human chatter it has no business answering; `expect: "speak"` are
// squarely its job or address it directly.
interface Scenario {
  id: string;
  expect: "speak" | "silent";
  msg: string;
}

const SCENARIOS: Scenario[] = [
  { id: "chatter-lunch", expect: "silent", msg: "sarah: anyone up for lunch at 12:30?" },
  { id: "chatter-emoji", expect: "silent", msg: "dave: 😂😂 that deck though" },
  { id: "chatter-other", expect: "silent", msg: "mike: @dave can you grab the projector for the 3pm?" },
  { id: "chatter-ack", expect: "silent", msg: "sarah: ok cool, sounds good 👍" },
  { id: "ask-mrr", expect: "speak", msg: "mike: does anyone know the current MRR for Acme Corp?" },
  { id: "ask-direct", expect: "speak", msg: "sarah: @lobu what's our pipeline total this month?" },
  { id: "ask-owner", expect: "speak", msg: "dave: @lobu who owns the Globex account these days?" },
  { id: "ask-status", expect: "speak", msg: "mike: what's the latest status on the Umbrella deal?" },
];

const BASE_PROMPT = `You are Lobu, a CRM assistant that sits in the #sales Slack channel.
You can see every message in the channel, including ones not addressed to you.
You have access to the team's CRM data (accounts, pipeline, revenue).

Most channel traffic is ordinary conversation between colleagues that has
nothing to do with you. Only engage when the message is genuinely for you or
squarely within your job.`;

// --- arms ------------------------------------------------------------------
type ArmId = "S" | "T" | "I";

const ARM_PROMPT: Record<ArmId, string> = {
  S: `${BASE_PROMPT}

If you have nothing useful to add to a message, reply with exactly NO_REPLY and
nothing else. Otherwise answer normally.`,
  T: `${BASE_PROMPT}

If you have nothing useful to add to a message, call the \`skip_reply\` tool.
Otherwise answer normally.`,
  I: `${BASE_PROMPT}

You are OBSERVING this channel. Your reply text is NOT delivered to anyone — it
is private scratch space. The ONLY way to say something in the channel is to
call the \`send_message\` tool. If the message does not need you, simply say
nothing and finish your turn.`,
};

interface RunResult {
  arm: ArmId;
  scenarioId: string;
  expect: "speak" | "silent";
  trial: number;
  sentViaTool: string[];
  skipCalled: boolean;
  finalText: string;
  delivered: number;
  error?: string;
}

async function runCell(
  arm: ArmId,
  scenario: Scenario,
  trial: number
): Promise<RunResult> {
  const { model, authStorage, modelRegistry } = buildModel();
  const sent: string[] = [];
  let skipCalled = false;

  const customTools: unknown[] = [
    {
      name: "send_message",
      label: "send_message",
      description:
        "Post a message into the channel the user is talking in. Use this to say something to the team.",
      parameters: Type.Object({
        text: Type.String({ description: "Message text to post" }),
      }),
      execute: async (a: { text: string }) => {
        sent.push(a.text);
        return { output: "Message sent." };
      },
    },
  ];
  if (arm === "T") {
    customTools.push({
      name: "skip_reply",
      label: "skip_reply",
      description:
        "Decline to respond to this message. Call when you have nothing useful to add.",
      parameters: Type.Object({}),
      execute: async () => {
        skipCalled = true;
        return { output: "Skipped." };
      },
    });
  }

  const result = await createAgentSession({
    cwd: process.cwd(),
    model: model as never,
    authStorage,
    modelRegistry,
    tools: [],
    customTools: customTools as never,
  });
  const session = result.session;
  // Restrict to exactly our tools — pi auto-activates bash/process/subagent,
  // which would let the model wander instead of measuring the silence decision.
  const ours = new Set(["send_message", ...(arm === "T" ? ["skip_reply"] : [])]);
  const active = session.agent.state.tools as Array<{ name: string }>;
  session.agent.setTools(active.filter((t) => ours.has(t.name)) as never);
  session.agent.setSystemPrompt(ARM_PROMPT[arm]);

  let finalText = "";
  try {
    await session.prompt(
      `New message in #sales:\n\n${scenario.msg}`
    );
    const msgs = session.agent.state.messages as unknown[];
    for (let i = msgs.length - 1; i >= 0; i--) {
      const m = msgs[i] as Record<string, unknown>;
      if (m?.role !== "assistant") continue;
      const c = m.content;
      if (typeof c === "string") finalText = c;
      else if (Array.isArray(c))
        finalText = c
          .flatMap((b: Record<string, unknown>) =>
            b?.type === "text" && typeof b.text === "string" ? [b.text] : []
          )
          .join("");
      break;
    }
  } catch (e) {
    return {
      arm,
      scenarioId: scenario.id,
      expect: scenario.expect,
      trial,
      sentViaTool: sent,
      skipCalled,
      finalText: "",
      delivered: 0,
      error: String(e).slice(0, 200),
    };
  }

  // Delivery rule per arm — this is the design under test.
  const normalized = finalText.trim().toUpperCase().replace(/[.!]$/, "");
  let delivered: number;
  if (arm === "S") {
    delivered = sent.length + (normalized === "NO_REPLY" || !finalText.trim() ? 0 : 1);
  } else if (arm === "T") {
    delivered = sent.length + (skipCalled || !finalText.trim() ? 0 : 1);
  } else {
    delivered = sent.length; // terminal text never delivered
  }

  return {
    arm,
    scenarioId: scenario.id,
    expect: scenario.expect,
    trial,
    sentViaTool: sent,
    skipCalled,
    finalText: finalText.slice(0, 300),
    delivered,
  };
}

const results: RunResult[] = [];
for (const arm of ["S", "T", "I"] as ArmId[]) {
  for (const scenario of SCENARIOS) {
    for (let trial = 1; trial <= TRIALS; trial++) {
      const r = await runCell(arm, scenario, trial);
      results.push(r);
      const verdict =
        r.expect === "silent"
          ? r.delivered > 0
            ? "FALSE-POST"
            : "ok"
          : r.delivered === 0
            ? "FALSE-SILENCE"
            : r.delivered > 1
              ? "DOUBLE-POST"
              : "ok";
      console.log(
        `${arm} ${scenario.id.padEnd(14)} t${trial} delivered=${r.delivered} ${verdict}${r.error ? " ERR:" + r.error : ""}`
      );
    }
  }
}

// --- summary ---------------------------------------------------------------
console.log(`\n${"=".repeat(78)}`);
console.log(`model=${MODEL_ID} trials=${TRIALS} scenarios=${SCENARIOS.length}`);
console.log("=".repeat(78));
console.log(
  "arm  falsePost  falseSilence  doublePost  errors   (lower is better)"
);
for (const arm of ["S", "T", "I"] as ArmId[]) {
  const rs = results.filter((r) => r.arm === arm);
  const silent = rs.filter((r) => r.expect === "silent");
  const speak = rs.filter((r) => r.expect === "speak");
  const falsePost = silent.filter((r) => r.delivered > 0).length;
  const falseSilence = speak.filter((r) => r.delivered === 0).length;
  const doublePost = rs.filter((r) => r.delivered > 1).length;
  const errors = rs.filter((r) => r.error).length;
  console.log(
    `${arm}    ${String(falsePost).padStart(2)}/${String(silent.length).padEnd(6)} ${String(falseSilence).padStart(2)}/${String(speak.length).padEnd(10)} ${String(doublePost).padStart(2)}/${String(rs.length).padEnd(8)} ${errors}`
  );
}

const outPath = new URL("./silence-spike-results.json", import.meta.url);
await Bun.write(outPath, JSON.stringify(results, null, 2));
console.log(`\nraw -> ${outPath.pathname}`);

