3. **Files and Code Sections:**

   - **`packages/server/src/gateway/conversations/conversation-ref.ts`** (NEW) — the comparison primitive. Exists because a top-level Slack DM arrives as `slack:D0123:` with an EMPTY trailing segment; naive `===` reports a false mismatch for every DM.
     ```ts
     export interface ConversationRef {
       channelKey: string;
       threadId?: string;
     }
     export function parseConversationRef(
       conversationId: string | undefined
     ): ConversationRef | null {
       if (!conversationId) return null;
       const [platform, channelId, ...rest] = conversationId.split(":");
       if (!platform || !channelId) return null;
       const threadId = rest.join(":");
       return {
         channelKey: `${platform}:${channelId}`,
         ...(threadId ? { threadId } : {}),
       };
     }
     export function conversationRefsMatch(
       a: ConversationRef | null,
       b: ConversationRef | null
     ): boolean {
       if (!a || !b) return false;
       return a.channelKey === b.channelKey && a.threadId === b.threadId;
     }
     ```

   - **`packages/server/src/gateway/routes/internal/conversations.ts`** — the decision point (only place that can resolve opaque handle → coords):
