// Walk back to the LAST assistant message that actually carries text.
// Breaking on the first assistant message from the end is wrong: a turn
// that ends in a tool call has a trailing tool-call-only assistant message
// with no text block, which read as "" and pinned delivered=0 everywhere.
// Stop at the user message so we only read this turn.
const msgs = session.agent.state.messages as unknown[];
for (let i = msgs.length - 1; i >= 0; i--) {
  const m = msgs[i] as Record<string, unknown>;
  if (m?.role === "user") break;
  if (m?.role !== "assistant") continue;
  const c = m.content;
  const text =
    typeof c === "string"
