input.new_string:
// Collapsing onto ANY carried identity is the documented contract
// (`AccessIdentitySpec`), but when a member's claims point at DIFFERENT
// entities that contract does not say which wins — and stopping at the first
// array hit made it depend on the order a connector happened to push its
// identities. `member_of` is a read ACL, so that is a mis-grant waiting to
// happen: a stale or recycled secondary claim (an old email, a reused login)
// would hand one person another person's channel access. Break the tie on the
// source's `primary` namespace — its own stable per-account key — and log the
// ambiguity, mirroring the 'multiple entities matched' warning that
// entity-link-upsert already emits.
const primaryNamespaces = new Set(
  memberIdentities.filter((s) => s.primary).map((s) => s.namespace)
);
const toCreate: AccessMember[] = [];
for (const m of members) {
  let primaryHit: number | undefined;
  let secondaryHit: number | undefined;
  const matched = new Set<number>();
  for (const id of m.identities) {
    const found = existing.get(`${id.namespace}|${id.value}`);
    if (found === undefined) continue;
    matched.add(found);
    if (primaryNamespaces.has(id.namespace)) primaryHit ??= found;
    else secondaryHit ??= found;
  }
  const hit = primaryHit ?? secondaryHit;
  if (matched.size > 1) {
    logger.warn(
      {
        organization_id: orgId,
        connector_key: connectorKey,
        member_key: m.key,
        matched_entity_ids: [...matched],
        resolved_to: hit,
      },
      'access-graph: member matched multiple entities at once — resolved via the primary identity'
    );
  }
  if (hit !== undefined) byKey.set(m.key, hit);
  else toCreate.push(m);
}

