/**
 * `resolveMembers` resolution safety — the ACL engine's member-side matcher.
 *
 * `member_of` edges are a READ ACL, so who a member resolves to decides who can
 * recall a channel's messages. Two resolution hazards are covered here:
 *
 *   1. A soft-DELETED entity still owns its identity rows (an ordinary delete
 *      does not tombstone them the way a merge repoints them). Resolving onto it
 *      writes edges to a dead entity and never mints a replacement, so the member
 *      silently drops out of the audience.
 *   2. A member whose identities match DIFFERENT entities is ambiguous. Picking
 *      by identity-array order is undefined behaviour on an access-control path:
 *      a stale or shared secondary claim (an old email, a recycled login) would
 *      hand one person another person's channel access. The source's `primary`
 *      namespace is its own stable per-account key, so it governs alone — it
 *      wins a cross-tier conflict, and when PRESENT it never falls through to
 *      a secondary match (a fresh primary means a distinct account, even while
 *      a recycled secondary still points at the old person). Only a member with
 *      no primary claim at all matches secondaries equal-weight. These are the
 *      tier semantics the entity-link create path already documents (`primary`
 *      in connector-types.ts); resolution must agree with creation.
 *
 * Uses the GitHub source because it already declares two member identities
 * (`github_user_id` primary + `github_login` — and a collaborator may carry
 * only the login), so every tier is a shipped shape.
 */

import {
  type GithubRepoInput,
  githubAclSource,
  githubReposToResources,
} from '@lobu/connectors/github-identity';
import { beforeEach, describe, expect, it } from 'vitest';
import { buildAccessGraph } from '../../../authz/access-graph';
import { clearEntityLinkRulesCache } from '../../../utils/entity-link-upsert';
import { cleanupTestDatabase, getTestDb } from '../../setup/test-db';
import {
  addUserToOrganization,
  createTestConnection,
  createTestEntity,
  createTestOrganization,
  createTestUser,
} from '../../setup/test-fixtures';

const CONN = 'conn-gh-resolution';

async function ensureType(orgId: string, slug: string, name: string): Promise<void> {
  const sql = getTestDb();
  await sql`
    INSERT INTO entity_types (organization_id, slug, name, created_at, updated_at)
    VALUES (${orgId}, ${slug}, ${name}, current_timestamp, current_timestamp)
    ON CONFLICT (organization_id, slug) WHERE organization_id IS NOT NULL AND deleted_at IS NULL
    DO NOTHING
  `;
}

async function seedOrg(name: string) {
  const org = await createTestOrganization({ name });
  const user = await createTestUser();
  await addUserToOrganization(user.id, org.id, 'owner');
  await ensureType(org.id, 'person', 'Person');
  return { org, user };
}

async function addIdentity(
  orgId: string,
  entityId: number,
  namespace: string,
  identifier: string
): Promise<void> {
  const sql = getTestDb();
  await sql`
    INSERT INTO entity_identities (organization_id, entity_id, namespace, identifier, source_connector)
    VALUES (${orgId}, ${entityId}, ${namespace}, ${identifier}, 'connector:github')
  `;
}

async function livePersons(orgId: string) {
  const sql = getTestDb();
  return sql<{ id: number; name: string }[]>`
    SELECT e.id, e.name
    FROM entities e
    JOIN entity_types et ON et.id = e.entity_type_id
    WHERE e.organization_id = ${orgId} AND et.slug = 'person' AND e.deleted_at IS NULL
    ORDER BY e.id
  `;
}

async function memberOfFromIds(orgId: string): Promise<number[]> {
  const sql = getTestDb();
  const rows = await sql<{ from_entity_id: number }[]>`
    SELECT r.from_entity_id
    FROM entity_relationships r
    JOIN entity_relationship_types rt ON rt.id = r.relationship_type_id
    WHERE r.organization_id = ${orgId}
      AND rt.slug = 'member_of'
      AND r.deleted_at IS NULL
    ORDER BY r.from_entity_id
  `;
  return rows.map((r) => Number(r.from_entity_id));
}

function buildGraph(params: {
  organizationId: string;
  connectionId: string;
  repos: GithubRepoInput[];
}) {
  return buildAccessGraph({
    organizationId: params.organizationId,
    connectionId: params.connectionId,
    connectorKey: githubAclSource.key,
    resourceNamespace: githubAclSource.resourceNamespace,
    memberIdentities: githubAclSource.memberIdentities,
    resources: githubReposToResources(params.repos),
  });
}

describe('access graph member resolution', () => {
  beforeEach(async () => {
    await cleanupTestDatabase();
    clearEntityLinkRulesCache();
  });

  it('does not resolve a member onto a SOFT-DELETED entity', async () => {
    const { org, user } = await seedOrg('Deleted Owner Org');
    const gh = await createTestConnection({
      organization_id: org.id,
      connector_key: 'github',
      slug: CONN,
      created_by: user.id,
    });

    // An entity that owns the member's identity, then gets ordinarily deleted.
    // An ordinary delete does NOT move or tombstone its identity rows.
    const dead = await createTestEntity({
      organization_id: org.id,
      entity_type: 'person',
      name: 'Deleted Person',
      created_by: user.id,
    });
    await addIdentity(org.id, dead.id, 'github_user_id', '501');
    const sql = getTestDb();
    await sql`
      UPDATE entities SET deleted_at = current_timestamp
      WHERE id = ${dead.id} AND organization_id = ${org.id}
    `;

    await buildGraph({
      organizationId: org.id,
      connectionId: String(gh.id),
      repos: [
        {
          fullName: 'acme/widgets',
          collaborators: [{ id: 501, login: 'ghost' }],
        },
      ],
    });

    const edgeFroms = await memberOfFromIds(org.id);
    // The dead entity must never gain an edge — it cannot read anything, so an
    // edge to it silently removes the member from the audience.
    expect(edgeFroms).not.toContain(dead.id);

    // A live replacement person must exist and own the edge instead.
    const persons = await livePersons(org.id);
    expect(persons).toHaveLength(1);
    expect(edgeFroms).toEqual([persons[0].id]);
  });

  it('resolves an ambiguous member deterministically via the PRIMARY identity', async () => {
    const { org, user } = await seedOrg('Ambiguous Org');
    const gh = await createTestConnection({
      organization_id: org.id,
      connector_key: 'github',
      slug: CONN,
      created_by: user.id,
    });

    // Two DIFFERENT live entities, each owning one of the member's claims.
    // `github_user_id` is the source's primary (stable, per-account) key;
    // `github_login` is secondary and can be recycled to another account.
    const byPrimary = await createTestEntity({
      organization_id: org.id,
      entity_type: 'person',
      name: 'Real Account',
      created_by: user.id,
    });
    await addIdentity(org.id, byPrimary.id, 'github_user_id', '777');

    const bySecondary = await createTestEntity({
      organization_id: org.id,
      entity_type: 'person',
      name: 'Recycled Login Holder',
      created_by: user.id,
    });
    await addIdentity(org.id, bySecondary.id, 'github_login', 'octocat');

    await buildGraph({
      organizationId: org.id,
      connectionId: String(gh.id),
      repos: [
        {
          fullName: 'acme/widgets',
          collaborators: [{ id: 777, login: 'octocat' }],
        },
      ],
    });

    const edgeFroms = await memberOfFromIds(org.id);
    // The primary claim wins; the recycled-login holder must NOT inherit access.
    expect(edgeFroms).toEqual([byPrimary.id]);
    expect(edgeFroms).not.toContain(bySecondary.id);
  });

  it('does NOT fall through to a secondary match when the primary is present but unmatched', async () => {
    const { org, user } = await seedOrg('Recycled Login Org');
    const gh = await createTestConnection({
      organization_id: org.id,
      connector_key: 'github',
      slug: CONN,
      created_by: user.id,
    });

    // Only the SECONDARY claim matches: 'octocat' was recycled to a brand-new
    // account (fresh github_user_id that matches nothing). Collapsing onto the
    // old login holder would hand them the new account's repo access.
    const oldHolder = await createTestEntity({
      organization_id: org.id,
      entity_type: 'person',
      name: 'Old Login Holder',
      created_by: user.id,
    });
    await addIdentity(org.id, oldHolder.id, 'github_login', 'octocat');

    await buildGraph({
      organizationId: org.id,
      connectionId: String(gh.id),
      repos: [
        {
          fullName: 'acme/widgets',
          collaborators: [{ id: 999, login: 'octocat' }],
        },
      ],
    });

    const edgeFroms = await memberOfFromIds(org.id);
    expect(edgeFroms).not.toContain(oldHolder.id);

    // A distinct person was minted for the new account and owns the edge.
    const persons = await livePersons(org.id);
    expect(persons).toHaveLength(2);
    const minted = persons.find((p) => p.id !== oldHolder.id);
    expect(minted).toBeDefined();
    expect(edgeFroms).toEqual([minted?.id]);
  });

  it('still collapses equal-weight on a secondary when the member carries NO primary claim', async () => {
    const { org, user } = await seedOrg('Login Only Org');
    const gh = await createTestConnection({
      organization_id: org.id,
      connector_key: 'github',
      slug: CONN,
      created_by: user.id,
    });

    // The GitHub collaborators shape may omit the numeric id; the login is then
    // the member's only claim and must keep matching (no duplicate person).
    const holder = await createTestEntity({
      organization_id: org.id,
      entity_type: 'person',
      name: 'Login Holder',
      created_by: user.id,
    });
    await addIdentity(org.id, holder.id, 'github_login', 'hubot');

    await buildGraph({
      organizationId: org.id,
      connectionId: String(gh.id),
      repos: [
        {
          fullName: 'acme/widgets',
          collaborators: [{ login: 'hubot' }],
        },
      ],
    });

    const edgeFroms = await memberOfFromIds(org.id);
    expect(edgeFroms).toEqual([holder.id]);
    expect(await livePersons(org.id)).toHaveLength(1);
  });
});

/**
 * GitHub repo-membership graph contract — proves the generic `buildAccessGraph`
 * engine generalizes to a SECOND source. Repos become `repo` entities keyed on
 * `github_repo_full_name`, collaborators become persons joined by `member_of`
 * edges, a collaborator who already exists (carrying a `github_user_id` claim)
 * COLLAPSES onto that entity (the identity-first fix the original org-level
 * GitHub builder lacked), departures reconcile, and the build stamps
 * `authz_source_acl_state`.
 */

import {
  type GithubRepoInput,
  githubAclSource,
  githubReposToResources,
  normalizeGithubRepoFullName,
} from '@lobu/connectors/github-identity';
import { beforeEach, describe, expect, it } from 'vitest';
import { buildAccessGraph } from '../../../authz/access-graph';
import { clearEntityLinkRulesCache } from '../../../utils/entity-link-upsert';

/**
 * Test helper: materialize a GitHub repo graph via the connector normalizer +
 * the generic engine — the same composition the GitHub ACL sync now does.
 */
function buildGithubRepoGraph(params: {
  organizationId: string;
  connectionId: string;
  repos: GithubRepoInput[];
}) {
  return buildAccessGraph({
    organizationId: params.organizationId,
    connectionId: params.connectionId,
    connectorKey: githubAclSource.key,
    resourceNamespace: githubAclSource.resourceNamespace,
    memberIdentities: githubAclSource.memberIdentities,
    resources: githubReposToResources(params.repos),
  });
}
import { cleanupTestDatabase, getTestDb } from '../../setup/test-db';
import {
  addUserToOrganization,
  createTestConnection,
  createTestEntity,
  createTestOrganization,
  createTestUser,
} from '../../setup/test-fixtures';

const CONN = 'conn-gh';

async function ensureType(orgId: string, slug: string, name: string): Promise<void> {
  const sql = getTestDb();
  await sql`
    INSERT INTO entity_types (organization_id, slug, name, created_at, updated_at)
    VALUES (${orgId}, ${slug}, ${name}, current_timestamp, current_timestamp)
    ON CONFLICT (organization_id, slug) WHERE organization_id IS NOT NULL AND deleted_at IS NULL
    DO NOTHING
  `;
}

async function seedOrg(name: string) {
  const org = await createTestOrganization({ name });
  const user = await createTestUser();
  await addUserToOrganization(user.id, org.id, 'owner');
  // The engine auto-creates `person` entities for collaborators; the type must
  // exist in the org (prod seeds default types at org creation).
  await ensureType(org.id, 'person', 'Person');
  return { org, user };
}

async function entitiesOfType(orgId: string, slug: string) {
  const sql = getTestDb();
  return sql<{ id: number; name: string }[]>`
    SELECT e.id, e.name
    FROM entities e
    JOIN entity_types et ON et.id = e.entity_type_id
    WHERE e.organization_id = ${orgId} AND et.slug = ${slug} AND e.deleted_at IS NULL
    ORDER BY e.id
  `;
}

async function memberOfEdges(orgId: string) {
  const sql = getTestDb();
  return sql<{ from_entity_id: number; to_entity_id: number }[]>`
    SELECT r.from_entity_id, r.to_entity_id
    FROM entity_relationships r
    JOIN entity_relationship_types rt ON rt.id = r.relationship_type_id
    WHERE r.organization_id = ${orgId}
      AND rt.slug = 'member_of'
      AND r.deleted_at IS NULL
    ORDER BY r.from_entity_id
  `;
}

describe('github repo graph', () => {
  beforeEach(async () => {
    await cleanupTestDatabase();
    clearEntityLinkRulesCache();
  });

  it('builds repo entities + member_of edges and marks the connection enforced', async () => {
    const { org } = await seedOrg('GitHub Graph Org');

    const result = await buildGithubRepoGraph({
      organizationId: org.id,
      connectionId: CONN,
      repos: [
        {
          fullName: 'lobu-ai/lobu',
          collaborators: [
            { login: 'alice', id: 101 },
            { login: 'bob', id: 102 },
          ],
        },
        { fullName: 'lobu-ai/secret', collaborators: [{ login: 'bob', id: 102 }] },
      ],
    });

    // Repo entities are keyed on the normalized (lowercased) full name.
    expect(Object.keys(result.resourceEntityIds).sort()).toEqual([
      normalizeGithubRepoFullName('lobu-ai/lobu'),
      normalizeGithubRepoFullName('lobu-ai/secret'),
    ]);
    // 3 edges: (alice,lobu), (bob,lobu), (bob,secret).
    expect(result.createdEdges).toBe(3);

    expect(await entitiesOfType(org.id, '$resource')).toHaveLength(2);
    expect(await entitiesOfType(org.id, 'person')).toHaveLength(2); // alice + bob

    const sql = getTestDb();
    const stateRows = await sql`
      SELECT acl_support, freshness_state FROM authz_source_acl_state
      WHERE organization_id = ${org.id} AND connection_id = ${CONN}
    `;
    expect(stateRows).toHaveLength(1);
    expect(stateRows[0].acl_support).toBe('full');
    expect(stateRows[0].freshness_state).toBe('fresh');
  });

  it('scopes identity provenance lookup to the graph connector', async () => {
    const { org, user } = await seedOrg('GitHub Provenance Org');
    const decoy = await createTestConnection({
      organization_id: org.id,
      connector_key: 'slack',
      created_by: user.id,
      createDefaultFeed: false,
    });
    const github = await createTestConnection({
      organization_id: org.id,
      connector_key: 'github',
      created_by: user.id,
      createDefaultFeed: false,
    });
    const sql = getTestDb();
    await sql`
      UPDATE connections
      SET slug = ${`agentconn-${github.id}`}
      WHERE id = ${decoy.id}
    `;

    await buildGithubRepoGraph({
      organizationId: org.id,
      connectionId: String(github.id),
      repos: [{ fullName: 'lobu-ai/lobu', collaborators: [{ login: 'alice', id: 101 }] }],
    });

    const identities = await sql<{ connection_id: number | null }[]>`
      SELECT connection_id
      FROM entity_identities
      WHERE organization_id = ${org.id}
        AND source_connector = 'connector:github'
    `;
    expect(identities.length).toBeGreaterThan(0);
    expect(identities.every((row) => Number(row.connection_id) === github.id)).toBe(true);
  });

  it('collapses a collaborator onto an existing entity carrying github_user_id (no second person)', async () => {
    const { org, user } = await seedOrg('Collapse Org');
    // A $member who already has a github_user_id claim (e.g. signed in + linked).
    const entity = await createTestEntity({
      name: 'Alice',
      entity_type: '$member',
      organization_id: org.id,
      created_by: user.id,
    });
    const sql = getTestDb();
    await sql`
      INSERT INTO entity_identities (organization_id, entity_id, namespace, identifier, source_connector)
      VALUES (${org.id}, ${entity.id}, 'github_user_id', '101', 'connector:github')
    `;
    expect(await entitiesOfType(org.id, 'person')).toHaveLength(0);

    const result = await buildGithubRepoGraph({
      organizationId: org.id,
      connectionId: CONN,
      repos: [{ fullName: 'lobu-ai/lobu', collaborators: [{ login: 'alice', id: 101 }] }],
    });

    // Alice resolved to her existing $member — NOT a new person.
    expect(await entitiesOfType(org.id, 'person')).toHaveLength(0);
    expect(result.memberEntityIds).toEqual([entity.id]);
    const edges = await memberOfEdges(org.id);
    expect(edges).toHaveLength(1);
    expect(edges[0].from_entity_id).toBe(entity.id);
  });

  it('reconciles departures: a collaborator removed on re-sync loses their edge', async () => {
    const { org } = await seedOrg('Reconcile Org');
    await buildGithubRepoGraph({
      organizationId: org.id,
      connectionId: CONN,
      repos: [
        {
          fullName: 'lobu-ai/lobu',
          collaborators: [
            { login: 'alice', id: 101 },
            { login: 'bob', id: 102 },
          ],
        },
      ],
    });
    expect(await memberOfEdges(org.id)).toHaveLength(2);

    // Bob is removed from the repo → re-sync with just Alice.
    const result = await buildGithubRepoGraph({
      organizationId: org.id,
      connectionId: CONN,
      repos: [{ fullName: 'lobu-ai/lobu', collaborators: [{ login: 'alice', id: 101 }] }],
    });
    expect(result.removedEdges).toBe(1);
    const edges = await memberOfEdges(org.id);
    expect(edges).toHaveLength(1);
  });
});

/**
 * ACL-source contract — the shared shape between a connector and the generic
 * access-graph engine.
 *
 * A connector that gates read access on membership (Slack channels, GitHub
 * repos, …) reduces to: RESOURCES × AUDIENCE of MEMBERS. The connector owns
 * normalization into that shape; the server materializes entities, identities,
 * and `member_of` edges. Core never names a connector.
 *
 * All ACL resources are entity type `$resource`. Sources differ only by
 * resource identity namespace and member identity namespaces.
 */

/**
 * Sole platform entity-type slug for ACL-gated units.
 * `$` prefix → system (hide rail, never prune, user-create blocked).
 */
export const ACL_RESOURCE_TYPE_SLUG = '$resource' as const;

/** Columns used when ensuring the platform `$resource` entity type. */
export const ACL_RESOURCE_TYPE = {
  slug: ACL_RESOURCE_TYPE_SLUG,
  name: 'Resource',
  description:
    'ACL-gated access unit (Slack channel, GitHub repository, …). Graph anchor only — empty metadata schema.',
  icon: 'shield',
} as const;

/**
 * A claim that identifies a member, e.g. `{namespace:'slack_user_id', primary:true}`.
 * The engine collapses a member onto an existing entity of any type carrying
 * their identities, with `primary` (the source's stable per-account key)
 * governing: a present primary matches alone and never falls through to a
 * secondary claim, and creation keys on it. Without a primary, secondary
 * claims match equal-weight; a same-tier conflict resolves nobody.
 */
export interface AccessIdentitySpec {
  namespace: string;
  primary?: boolean;
}

/** One member of a resource's audience. */
export interface AccessMember {
  /** Stable dedupe key (e.g. `T…:U…` for Slack, numeric id for GitHub). */
  key: string;
  /** Display name for an auto-created `person`. Falls back to `key`. */
  name?: string;
  /** This member's identity claims (namespaces in `memberIdentities`). */
  identities: { namespace: string; value: string }[];
}

/** One resource (channel/repo/…) and the members who may read it. */
export interface AccessResource {
  /**
   * Stored under the source's `resourceNamespace`
   * (`T…:C…` for Slack, `owner/repo` for GitHub).
   */
  key: string;
  name?: string;
  members: AccessMember[];
}

/**
 * A connector's ACL-source descriptor — the ONE thing a connector declares to
 * become access-controlled. All resources materialize as `$resource`; only the
 * identity namespaces are source-specific.
 */
export interface AclSourceDef {
  /** Connector/platform key (`slack`, `github`, …). */
  key: string;
  /**
   * Identity namespace for resource keys (e.g. `slack_channel_id`,
   * `github_repo_full_name`).
   */
  resourceNamespace: string;
  /** How a member of a resource is identified. */
  memberIdentities: AccessIdentitySpec[];
}

/**
 * A chat platform's READ-gate identity model — how the per-channel visibility
 * gate keys a channel and a requester for THIS platform. Unlike `AclSourceDef`
 * (pure data, persisted, replayed generically) this carries key-BUILDER
 * functions, so it is used only in-process at the server's authz edge.
 *
 * A binding stores a bare channel id (`C…`) + a tenant/team id; the gate must
 * reconstruct the exact team-scoped key the ACL sync wrote (`T…:C…`) to match
 * the graphed `$resource` entity.
 */
export interface ChannelReadIdentity {
  /** Platform key (`slack`, …) — matched against a binding's `platform`. */
  platform: string;
  /** Identity namespace a channel resource entity is stored under. */
  channelNamespace: string;
  /** Identity namespace a requester (channel member) is stored under. */
  userNamespace: string;
  /**
   * Build the team-scoped channel key (`T…:C…`) from a tenant/team id and a
   * BARE channel id. Returns null when the inputs can't form a valid key.
   */
  buildChannelKey(teamId: string | null | undefined, bareChannelId: string): string | null;
  /**
   * Build the team-scoped requester key (`T…:U…`) from a tenant/team id and a
   * bare user id. Returns null when the inputs can't form a valid key.
   */
  buildUserKey(teamId: string | null | undefined, userId: string | null | undefined): string | null;
  /**
   * The same channel-key construction as a SQL expression, given safe SQL
   * column expressions for team id and bare channel id.
   */
  channelKeySql(teamColExpr: string, channelColExpr: string): string;
}

