import io
p='packages/server/src/auth/index.tsx'
s=io.open(p,encoding='utf-8').read()
orig=s

# 1. registry import
s=s.replace('import { connectorCapabilityRegistry } from "../identity/capability-registry";\n','',1)

# 2. side-effect import + startup assertion
old_assert = '''// Side-effect imports: each connector self-registers on load, so the
// registry is fully populated before any auth hook can fire. Add a new
// import here when adding a connector under `../identity/connectors/`.
import "../identity/connectors/google";

if (connectorCapabilityRegistry.size() === 0) {
	throw new Error(
		"identity connector registry is empty — check side-effect imports in auth/index.tsx",
	);
}

import {
	scheduleIdentityIngest,
	scheduleIdentityTombstoneOnAccountDelete,
} from "../identity/auth-hook";
import { persistLoginSlackIdentity } from "./subject-identities";
'''
new_assert = 'import { persistLoginSlackIdentity } from "./subject-identities";\n'
assert s.count(old_assert)==1, 'assert block'
s=s.replace(old_assert,new_assert,1)

# 3. provider warning loop
old_warn = '''	// Warn for any enabled social provider that has no identity-engine
	// connector. Sign-in still works; facts simply aren't ingested. Connectors
	// are loaded statically at the top of the file, so the registry is
	// guaranteed populated by the time we reach this check.
	for (const provider of Object.keys(socialProviders)) {
		if (!connectorCapabilityRegistry.emitter(provider.trim().toLowerCase())) {
			console.warn(
				`[Auth] Social provider "${provider}" is enabled but has no identity connector — facts will not be ingested for sign-ins via this provider.`,
			);
		}
	}

'''
assert s.count(old_warn)==1, 'warn block'
s=s.replace(old_warn,'',1)

# 4. create.after ingest call
old_create = '''						// Identity engine ingest. Fire-and-forget; sign-in never blocks.
						scheduleIdentityIngest(accountSummary);
						// Slack sign-in: collapse'''
new_create = '''						// Slack sign-in: collapse'''
assert s.count(old_create)==1, 'create hook'
s=s.replace(old_create,new_create,1)

# 5. update.after ingest call
old_update = '''						scheduleIdentityIngest(accountSummary);
						// Slack re-link / token refresh: keep the slack_user_id stamped.'''
new_update = '''						// Slack re-link / token refresh: keep the slack_user_id stamped.'''
assert s.count(old_update)==1, 'update hook'
s=s.replace(old_update,new_update,1)

# 6. delete.after hook — existed solely to tombstone engine facts
old_delete = '''				delete: {
					after: async (account) => {
						// Unlinking an OAuth account must tombstone every fact we ever
						// ingested under it so derivations get revoked. Without this hook
						// disconnected providers keep producing reads forever.
						scheduleIdentityTombstoneOnAccountDelete({
							id: account.id,
							userId: account.userId,
							providerId: account.providerId,
						});
					},
				},
'''
assert s.count(old_delete)==1, 'delete hook'
s=s.replace(old_delete,'',1)

assert s!=orig
io.open(p,'w',encoding='utf-8').write(s)
print('auth/index.tsx unwired')
