'''
new = '''		// Redemption binds the chat and NOTHING ELSE. It deliberately records no
		// chat-platform → Lobu-user identity.
		//
		// It used to. The code is minted by an authenticated `lobu run` and was
		// ASSUMED to be redeemed by the same person, so redeeming stamped a
		// `chat_user_identities` row. That row is read by the Slack approval path
		// (`interaction-bridge` resolveSlackActionReviewer) and the in-chat
		// builder-admin grant, which made a paste-able claim code effectively a
		// credential for the minter's account — anyone who saw a code in a shared
		// channel could redeem it and inherit their approval authority.
		//
		// An assumption cannot back an authorization decision, so there is nothing
		// to repoint: chat identity is now established ONLY by real Slack OAuth,
		// which writes a provider-signed `account` row. The cost is that
		// `/lobu link <agentId>` re-binding needs a prior Slack sign-in.
'''
assert s.count(old)==1
s=s.replace(old,new,1)
io.open(p,'w',encoding='utf-8').write(s)
print('identity write removed')
