1	import { createHash, randomInt } from "node:crypto";
2	import { slugify } from "@lobu/core";
3	import type { Context } from "hono";
4	import { getDb } from "../db/client";
5	import { maybeSendSlackWorkspaceWelcome } from "../gateway/connections/slack-connection-coordinator";
6	import { parseJsonBody } from "../gateway/routes/shared/helpers";
7	import { SecretStoreRegistry } from "../gateway/secrets";
8	import { PostgresSecretStore } from "../lobu/stores/postgres-secret-store";
9	import type { Env } from "../index";
10	import { runtimeConnectionIdToSlug } from "../lobu/stores/connections-projection";
11	import { errorMessage } from "../utils/errors";
12	import logger from "../utils/logger";
13	import { getConfiguredPublicOrigin } from "../utils/public-origin";
14	import { requireOrgUser } from "../utils/require-org-user";
15	import { MANAGED_CHAT_PLATFORMS_SET } from "./managed-platforms";
16	import { BehaviorSubscriptionService } from "../gateway/channels/behavior-subscription-service";
17	
18	// Slack Preview lets people trying Lobu locally talk to their agent through the
19	// hosted "Lobu Developer" Slack workspace before they have their own bot token.
20	// There is no Slack-Preview-specific schema or transport:
21	//   * The link code lives in `oauth_states` (scope `slack-preview-claim`).
22	//   * The hosted "Lobu Developer" workspace is just an ordinary Slack
23	//     `connections` row (no env var, no relay service).
24	//   * `/lobu link <code>` in that workspace consumes the claim and writes a normal
25	//     message-created Behavior trigger — so inbound messages
26	//     route through the exact same Chat SDK adapter path every other platform
27	//     connection uses.
28	
29	// Slack DM channel ids start with `D`; the canonical binding key is `slack:<id>`.
30	const SLACK_PLATFORM = "slack";
31	const CLAIM_SCOPE = "slack-preview-claim";
32	const DEFAULT_TTL_MINUTES = 15;
33	const MAX_TTL_MINUTES = 60;
34	const SURFACES = new Set(["dm", "channel"]);
35	
36	// Hosted preview bots — the platforms a `preview.<platform>` block / claim mint
37	// is allowed for (currently Slack and Telegram), and the default join links.
38	// Both Slack and Telegram route through the same Chat SDK adapter path.
39	const PREVIEW_PLATFORMS = MANAGED_CHAT_PLATFORMS_SET;
40	const PREVIEW_JOIN_DEFAULTS: Record<string, string> = {
41		slack: "https://lobu.ai/slack",
42		telegram: "https://t.me/lobuaibot",
43	};
44	
45	type SurfaceType = "dm" | "channel";
46	
47	// Slash-command spellings differ by platform: Slack only delivers the
48	// natively-registered `/lobu`, so its subcommands are `/lobu try` etc.; other
49	// platforms register each command directly (`/try`, `/agents`, `/link`).
50	function tryCommand(platform: string): string {
51		return platform === "slack" ? "/lobu try" : "/try";
52	}
53	function listCommand(platform: string): string {
54		return platform === "slack" ? "/lobu agents" : "/agents";
55	}
56	function linkCommand(platform: string): string {
57		return platform === "slack" ? "/lobu link" : "/link";
58	}
59	
